WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_a1a009f35cb5ecaf>
    <urn:graphragprov:unit:u_d62dd842246356e8>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
